import { expect, expectStatus, test } from "../../fixtures";

test("an insurance certificate whose expiry date could not be read cannot be approved", { tag: "@LIF-08" }, async ({ apiAs, factory }) => {
  // Arrange
  const { extractions, documents } = await factory.vendorInReview({
    files: { insurance_certificate: "insurance_certificate_unparseable.txt" },
  });
  const reviewer = await apiAs("reviewer");

  // Act
  const response = await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expiry_missing");
  const extraction = await factory.extraction(documents.insurance_certificate.id, "reviewer");
  expect(extraction.status).toBe("pending_review");
});
